-- Source and independent-solution verification; no historical scores changed.
-- Before-images are retained in audit_log; rows in active exams are deferred.
DO $review$
DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "5860106c-a889-afe0-c86e-03f6585d615c", "before": {"stem": "Same setup as previous. P(AT LEAST ONE of the two selected biscuits is salty)?", "choices": [{"key": "A", "text": "3/88"}, {"key": "B", "text": "13/28"}, {"key": "C", "text": "2/9"}, {"key": "D", "text": "13/54"}], "correct": "B", "explanation": "Independently solved and checked against the original source page and printed choices."}, "source_question_id": "stats_probability_revision_may_2026-p9-q27", "source": "Stats & Probability Revision May 2026, page 9 Q28–29", "review_note": "Restored the shared setup from the original PDF and independently used the complement rule.", "release": true, "fields": {"stem": "A box contains 1 salty and 3 sweet biscuits. A bag contains 2 salty and 4 sweet biscuits. A biscuit is selected randomly from the box and placed in the bag, then a biscuit is selected randomly from the bag and placed in the box. What is the probability that at least one of the two selected biscuits is salty?"}, "explanation": "Neither selected biscuit is salty exactly when both are sweet. The first is sweet with probability 3/4; then the bag contains 5 sweet biscuits among 7, so P(both sweet) = (3/4)(5/7) = 15/28. Therefore P(at least one salty) = 1 − 15/28 = 13/28.", "correct": "B"}, {"id": "4e5d0e24-836e-5e18-85af-6868807dc27e", "before": {"stem": "A box contains 50 pens numbered from 1 to 50. What is half the probability that we would select a pen with a number that is divisible by two or by five?", "choices": [{"key": "A", "text": "0.70"}, {"key": "B", "text": "0.60"}, {"key": "C", "text": "0.35"}, {"key": "D", "text": "0.30"}], "correct": "D", "explanation": "There are 25 multiples of 2, 10 multiples of 5, and 5 overlaps. The union has 30 pens, probability 30/50. Half this is 0.30."}, "source_question_id": null, "source": "EST I Questions by Topic, page 37, DAP 049", "review_note": "Rechecked newly reported solution against the source: D is correct; clarified union overlap and the final halving.", "release": true, "fields": {}, "explanation": "Among 1–50 there are 25 multiples of 2 and 10 multiples of 5. The 5 multiples of 10 occur in both groups, so count them only once: 25 + 10 − 5 = 30 favorable pens. The probability is 30/50 = 0.60. The question asks for HALF of that probability: 0.60/2 = 0.30, choice D.", "correct": "D"}, {"id": "07931921-276e-5c7c-80d9-7b3df878d1ca", "before": {"stem": "An object is launched into the air. The table below shows the object's height above the ground at various times.\n[Table — Height vs. Time (Elapsed Time s | Height m): 1|78, 2|109, 3|131, 4|143, 5|145, 6|137]\nBased on the data in the table, which of the following is closest to the object's height above the ground 9 seconds after being launched?", "choices": [{"key": "A", "text": "110 m"}, {"key": "B", "text": "55 m"}, {"key": "C", "text": "10 m"}, {"key": "D", "text": "95 m"}], "correct": "B", "explanation": "Source-keyed answer from moh.md (MA-15)."}, "source_question_id": "MA-15", "source": "Kimi supplied transcription, moh.md MA-15; original PDF unavailable", "review_note": "Verified the complete stored table independently. Added an explicit quadratic best-fit model; original PDF fidelity is not asserted.", "release": true, "fields": {"stem": "An object is launched into the air. At times t = 1, 2, 3, 4, 5, and 6 seconds, its measured heights are 78, 109, 131, 143, 145, and 137 meters, respectively. Using a quadratic best-fit model for these data, which listed value is closest to its predicted height at t = 9 seconds?"}, "explanation": "A quadratic least-squares fit to the six time-height pairs is h(t) ≈ -4.910714t² + 46.232143t + 36.500000. At t = 9 it predicts h(9) ≈ 54.821 m. The closest listed height is 55 m.", "correct": "B"}, {"id": "664e3a55-dcae-5dff-af2d-7c9ae7562787", "before": {"stem": "An object is launched into the air. The table below shows the object's height above the ground at various times.\n[Table — Height vs. Time (Elapsed Time s | Height m): 1|78, 2|109, 3|131, 4|143, 5|145, 6|137]\nBased on the data in the table, which of the following is closest to the object's height above the ground 9 seconds after being launched?", "choices": [{"key": "A", "text": "110 m"}, {"key": "B", "text": "55 m"}, {"key": "C", "text": "10 m"}, {"key": "D", "text": "95 m"}], "correct": "B", "explanation": "Source-keyed answer from moh.md (MA-15)."}, "source_question_id": "MA-15", "source": "Kimi supplied transcription, moh.md MA-15; original PDF unavailable", "review_note": "Verified the complete stored table independently. Added an explicit quadratic best-fit model; original PDF fidelity is not asserted.", "release": true, "fields": {"stem": "An object is launched into the air. At times t = 1, 2, 3, 4, 5, and 6 seconds, its measured heights are 78, 109, 131, 143, 145, and 137 meters, respectively. Using a quadratic best-fit model for these data, which listed value is closest to its predicted height at t = 9 seconds?"}, "explanation": "A quadratic least-squares fit to the six time-height pairs is h(t) ≈ -4.910714t² + 46.232143t + 36.500000. At t = 9 it predicts h(9) ≈ 54.821 m. The closest listed height is 55 m.", "correct": "B"}, {"id": "1f157430-f01c-294b-c4ef-36929bf5ddf8", "before": {"stem": "Ahmed spells 10 words in 60 sec. How many in 1 min 20 sec?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "3"}, {"key": "C", "text": "13"}, {"key": "D", "text": "14"}], "correct": "C", "explanation": "Independently solved and checked against the original source page and printed choices."}, "source_question_id": "stats_probability_revision_may_2026-p13-q42", "source": "Stats & Probability Revision May 2026, page 13; matching December source page 7", "review_note": "Made constant rate and complete-word counting explicit; independently checked the result.", "release": true, "fields": {"stem": "Ahmed spells words at a constant rate of 10 words per 60 seconds. How many complete words can he spell in 1 minute 20 seconds?"}, "explanation": "Each word takes 60/10 = 6 seconds. In 80 seconds Ahmed can finish 13 words, because 13 × 6 = 78 seconds, whereas 14 × 6 = 84 seconds.", "correct": "C"}, {"id": "2f9da61d-2cf6-fa6b-5700-fb3bc344ad0e", "before": {"stem": "Q35. Which equation describes the line graphed below? Abdelrahman", "choices": [{"key": "A", "text": "3x + 2y = 6"}, {"key": "B", "text": "2x + 3y = 6"}, {"key": "C", "text": "3x − 2y = 6"}, {"key": "D", "text": "y = 3x + 2\n\nAbdelrahman Ghoneem | 01116004434 | EST & SAT Math Page 8"}], "correct": "A", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00034", "source": "/workspace/scratch/e379d1a7362b/audit-sources/DOC-20260623-WA0016_260909_203219.pdf; physical page 8", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "Which equation describes the line shown in the graph?", "choices": [{"key": "A", "text": "3x + 2y = 6"}, {"key": "B", "text": "2x + 3y = 6"}, {"key": "C", "text": "3x − 2y = 6"}, {"key": "D", "text": "y = 3x + 2"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "The graph passes through (0,3) and (2,0). Its slope is (0 − 3)/(2 − 0) = −3/2 and its y-intercept is 3. Thus y = −3x/2 + 3, or 3x + 2y = 6.", "correct": "A"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260928' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260928','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260928','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-28-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-28-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-28-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260928','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260928'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260928')) AS result;
